import sys
from typing import List

def dfs(root: int, adj_list: List[List[int]], order: List[int], visited: List[bool]) -> None:
    stack = [root]
    while stack:
        node = stack.pop()
        if not visited[node]:
            visited[node] = True
            order.append(node)
            for neighbor in adj_list[node]:
                if not visited[neighbor]:
                    stack.append(neighbor)

